package com.careerguidance.controller; import com.careerguidance.constant.ResumeReviewStatus; import com.careerguidance.dto.request.*; import com.careerguidance.dto.response.*; import com.careerguidance.entity.Resume; import com.careerguidance.exception.ResumeNotFoundException; import com.careerguidance.repository.ResumeRepository; import com.careerguidance.service.MentorAccessService; import com.careerguidance.service.MentorReviewService; import jakarta.validation.Valid; import org.springframework.core.io.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.nio.file.*;
@RestController @RequestMapping("/api/mentor/students/{id}/resume") public class ResumeReviewController {private final MentorReviewService service;private final MentorAccessService access;private final ResumeRepository resumes;public ResumeReviewController(MentorReviewService s,MentorAccessService a,ResumeRepository r){service=s;access=a;resumes=r;} @GetMapping @org.springframework.security.access.prepost.PreAuthorize("hasRole('MENTOR')") public ResumeReviewResponse get(Authentication a,@PathVariable Long id){return service.resume(a,id);}@PostMapping("-feedback") @org.springframework.security.access.prepost.PreAuthorize("hasRole('MENTOR')") public MessageResponse feedback(Authentication a,@PathVariable Long id,@Valid @RequestBody ResumeFeedbackRequest r){service.resumeFeedback(a,id,r);return new MessageResponse("Resume feedback submitted");}@PatchMapping("/approve") @org.springframework.security.access.prepost.PreAuthorize("hasRole('MENTOR')") public MessageResponse approve(Authentication a,@PathVariable Long id,@Valid @RequestBody(required=false) ApproveResumeRequest r){service.review(a,id,ResumeReviewStatus.APPROVED,r==null?null:r.comment());return new MessageResponse("Resume approved");}@PatchMapping("/reject") @org.springframework.security.access.prepost.PreAuthorize("hasRole('MENTOR')") public MessageResponse reject(Authentication a,@PathVariable Long id,@Valid @RequestBody ResumeFeedbackRequest r){service.review(a,id,ResumeReviewStatus.REJECTED,r.feedback());return new MessageResponse("Resume rejected");}@GetMapping("/download") @org.springframework.security.access.prepost.PreAuthorize("hasRole('MENTOR')") public ResponseEntity<Resource> download(Authentication a,@PathVariable Long id)throws Exception{access.assigned(access.current(a),id);Resume r=resumes.findFirstByUserIdOrderByUploadTimeDesc(id).orElseThrow(()->new ResumeNotFoundException("Resume not found"));Path path=Paths.get(r.getFilePath()).normalize();if(!Files.isRegularFile(path))throw new ResumeNotFoundException("Resume file not found");return ResponseEntity.ok().contentType(MediaType.parseMediaType(r.getFileType())).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+r.getOriginalFileName().replace("\"","")+"\"").body(new FileSystemResource(path));}}
